// Starts a tool page. Each renderer/tool/pages/<id>.js entry (generated by scripts/build.mjs from
// pages.ts) imports its page and calls this.
import { api, args, h, shell } from '../shared/ui';

export type ToolPage = (paths: string[]) => void | Promise<void>;

/** Replaces the window's content with an error message. */
export function showError(title: string, message: string) {
  const s = shell({ title, layout: 'full' });
  s.full.append(h('p', { class: 'empty-state' }, message));
  s.primary.remove();
  s.cancel.textContent = 'Close';
}

function failed(e: any) {
  console.error(e);
  showError('Something went wrong', String(e?.message ?? e));
}

export function start(page: ToolPage) {
  try {
    // Called synchronously: the page builds its window before the document finishes loading.
    Promise.resolve(page(args<{ paths: string[] }>().paths)).catch(failed);
  } catch (e) {
    failed(e);
  }
}

/** Tells the native side the page is built, so the window is shown (1.x: ready-to-show). */
export function ready() {
  // Not requestAnimationFrame: it doesn't run while the window is still hidden.
  setTimeout(() => api().send('tool:ready'), 0);
}

/** Tools that run straight from the wheel without a window (extractArchive): the window stays
 *  hidden, runs the job (HUD shows progress) and closes. */
export async function runInstant() {
  const a = args<{ tool: string; paths: string[]; options?: unknown; title?: string }>();
  try {
    await api().invoke('tool:run', a.tool, a.paths, a.options, a.title);
  } finally {
    api().send('window:close');
  }
}
